using OrderManagement.Application.DTOs.Products;using OrderManagement.Application.Interfaces.Repositories;using OrderManagement.Application.Services;using OrderManagement.Domain.Entities;using Xunit;
namespace OrderManagement.Tests;public sealed class ProductServiceTests{[Fact]public async Task CreateAsync_MapsAndPersistsProduct(){var repo=new FakeRepo();var s=new ProductService(repo);var result=await s.CreateAsync(new CreateProductRequest{Name=" Notebook ",Price=100,Stock=2});Assert.Equal("Notebook",result.Name);Assert.Equal(100m,result.Price);Assert.NotNull(repo.LastAdded);}private sealed class FakeRepo:IProductRepository{public Product? LastAdded;public Task AddAsync(Product p,CancellationToken ct=default){LastAdded=p;return Task.CompletedTask;}public Task DeleteAsync(Product p,CancellationToken ct=default)=>Task.CompletedTask;public Task<IReadOnlyList<Product>> GetAllAsync(CancellationToken ct=default)=>Task.FromResult<IReadOnlyList<Product>>(Array.Empty<Product>());public Task<Product?> GetByIdAsync(Guid id,CancellationToken ct=default)=>Task.FromResult<Product?>(null);public Task UpdateAsync(Product p,CancellationToken ct=default)=>Task.CompletedTask;}}
